            if (trigger) {
                trigger.focus();
            }
        }

        this.currentImageId = null;
    }

    confirmDelete() {
        if (this.currentImageId) {
            console.log(`Deleting image with ID: ${this.currentImageId}`);

            // Find and remove the image card
            const imageCard = document.querySelector(`[data-image-id="${this.currentImageId}"]`).closest('.image-card');
            if (imageCard) {
                imageCard.style.animation = 'slideUp 0.3s ease reverse';
                setTimeout(() => {
                    imageCard.remove();
                    this.close();
                }, 300);
            } else {
                this.close();
            }
        }
    }

    handleKeydown(event) {
        if (event.key === 'Escape' && this.modal.classList.contains('active')) {
            this.close();
        }

        // Trap focus within the modal when it's active
        if (this.modal.classList.contains('active') && event.key === 'Tab') {
            this.manageFocus(event);
        }
    }

    manageFocus(event) {
        const focusableElements = this.modal.querySelectorAll(
            'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );
        const firstElement = focusableElements[0];
        const lastElement = focusableElements[focusableElements.length - 1];

        if (event.shiftKey) {
            if (document.activeElement === firstElement) {
                event.preventDefault();
                lastElement.focus();
            }
        } else {
            if (document.activeElement === lastElement) {
                event.preventDefault();
                firstElement.focus();
            }
        }
    }
}

