+class ModalDialog {
+    constructor() {
+        this.modal = document.getElementById('deleteModal');
+        this.overlay = this.modal.querySelector('.modal-overlay');
+        this.closeBtn = this.modal.querySelector('.modal-close');
+        this.cancelBtn = this.modal.querySelector('.modal-btn-cancel');
+        this.deleteBtn = this.modal.querySelector('.modal-btn-delete');
+        this.triggers = document.querySelectorAll('.trigger');
+        this.currentImageId = null;
+
+        this.init();
+    }
+
+    init() {
+        // Attach click handlers to all trigger buttons
+        this.triggers.forEach(trigger => {
+            trigger.addEventListener('click', (e) => this.open(e));
+        });
+
+        // Attach close handlers
+        this.closeBtn.addEventListener('click', () => this.close());
+        this.cancelBtn.addEventListener('click', () => this.close());
+        this.overlay.addEventListener('click', () => this.close());
+
+        // Delete confirmation
+        this.deleteBtn.addEventListener('click', () => this.confirmDelete());
+
+        // Keyboard handling
+        document.addEventListener('keydown', (e) => this.handleKeydown(e));
+    }
+
+    open(event) {
+        const imageId = event.target.getAttribute('data-image-id');
+        this.currentImageId = imageId;
+        this.modal.classList.add('active');
+        this.modal.setAttribute('aria-hidden', 'false');
+        
+        // Prevent body scroll when modal is open
+        document.body.style.overflow = 'hidden';
+
+        // Focus the delete button for better accessibility
+        this.deleteBtn.focus();
+    }
+
+    close() {
+        this.modal.classList.remove('active');
+        this.modal.setAttribute('aria-hidden', 'true');
+        
+        // Restore body scroll
+        document.body.style.overflow = '';
+
+        // Return focus to the trigger button that opened the modal
+        if (this.currentImageId) {
+            const trigger = document.querySelector(`[data-image-id="${this.currentImageId}"]`);
+            if (trigger) {
+                trigger.focus();
+            }
+        }
+
+        this.currentImageId = null;
+    }
+
+    confirmDelete() {
+        if (this.currentImageId) {
+            console.log(`Deleting image with ID: ${this.currentImageId}`);
+            
+            // Find and remove the image card
+            const imageCard = document.querySelector(`[data-image-id="${this.currentImageId}"]`).closest('.image-card');
+            if (imageCard) {
+                imageCard.style.animation = 'slideUp 0.3s ease reverse';
+                setTimeout(() => {
+                    imageCard.remove();
+                    this.close();
+                }, 300);
+            } else {
+                this.close();
+            }
+        }
+    }
+
+    handleKeydown(event) {
+        if (event.key === 'Escape' && this.modal.classList.contains('active')) {
+            this.close();
+        }
+
+        // Trap focus within the modal when it's active
+        if (this.modal.classList.contains('active') && event.key === 'Tab') {
+            this.manageFocus(event);
+        }
+    }
+
+    manageFocus(event) {
+        const focusableElements = this.modal.querySelectorAll(
+            'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
+        );
+        const firstElement = focusableElements[0];
+        const lastElement = focusableElements[focusableElements.length - 1];
+
+        if (event.shiftKey) {
+            if (document.activeElement === firstElement) {
+                event.preventDefault();
+                lastElement.focus();
+            }
+        } else {
+            if (document.activeElement === lastElement) {
+                event.preventDefault();
+                firstElement.focus();
+            }
+        }
+    }
+}
